const url = $json.body['Company URL'];

function extractDomain(url) {
  if (!url) return null;

  url = url.trim();

  // Remove protocol (http/https)
  url = url.replace(/^https?:\/\//, "");

  // Remove www.
  url = url.replace(/^www\./, "");

  // Get everything before first slash
  const host = url.split("/")[0];

  // Split into parts
  const parts = host.split(".");

  // If domain has only two parts (example.com), return as-is
  if (parts.length <= 2) {
    return host;
  }

  // Otherwise, take the LAST TWO parts (handles .com, .net, .xyz, .in, etc.)
  return parts.slice(-2).join(".");
}

return {
  domain: extractDomain(url)
};

