// --- find the inner Slack JSON string ---
function pick(...xs){return xs.find(v=>v!==undefined && v!==null);}
const root = pick($json.body, $json, $json.formData);
let inner = pick(
  root?.payload,
  $json.payload,
  $json.body?.payload,
  $json.formData?.payload
);

// ensure string
if (typeof inner !== 'string') inner = JSON.stringify(inner);

// if it arrived as "payload=...", strip
if (inner.startsWith('payload=')) inner = inner.slice(8);

// try parse; if fails, try URL-decode then parse
let p;
try { p = JSON.parse(inner); }
catch {
  try { p = JSON.parse(decodeURIComponent(inner)); }
  catch { throw new Error('Cannot parse Slack payload'); }
}

// extract fields
const action = Array.isArray(p.actions) && p.actions[0] ? p.actions[0] : {};
const [type, meetingId] = String(action.value || '').split('||');
const clickedType = type || null;

// get original blocks and remove the clicked button
let newBlocks = (p.message?.blocks || []).map(block => {
  if (block.type === 'actions' && Array.isArray(block.elements)) {
    return {
      ...block,
      elements: block.elements.filter(btn => {
        const [btnType] = String(btn.value || '').split('||');
        return btnType !== clickedType; // remove only the clicked type
      })
    };
  }
  return block;
});

// remove any empty actions blocks
newBlocks = newBlocks.filter(block => !(block.type === 'actions' && (!block.elements || block.elements.length === 0)));

return [{
  type: clickedType,
  meetingId: meetingId || null,
  action_id: action.action_id || null,
  channel: p.channel?.id ?? p.container?.channel_id ?? null,
  thread_ts: p.message?.ts ?? p.container?.message_ts ?? null,
  user_id: p.user?.id ?? null,
  response_url: p.response_url ?? null,
  blocks: { blocks: newBlocks }
}];

